'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),{Api}=require('teleproto'),bigInt=require('big-integer');
const {fillLink,checkPart}=require('../dist/nodes/NnaTelegramSender/bundle-content'),{validateBundle,publishBundle}=require('../dist/nodes/NnaTelegramSender/bundle-publish');
const now=Date.now(),c={expectedUserId:'42',allowedGroupId:'-1001234500000'};
function part(){return {text:'Heading\nLINK\n🙂',entities:[{type:'bold',offset:0,length:7},{type:'custom_emoji',offset:13,length:2,custom_emoji_id:'12345'}],linkOffset:8,linkLength:4};}
function params(){return {config:{reviewGroupId:'-1009876500000',reviewTopicId:3,botId:'99',operatorIds:['42'],targets:[{groupId:c.allowedGroupId,topicId:10}],bundlePairs:[{groupId:c.allowedGroupId,mediaTopicId:10,articleTopicId:20}]},delivery:{mode:'bundle',claimValidated:true,operatorId:'42',chatId:'42',topicId:0,revision:'123',requestKey:'media:42:42:0:123',approvedAt:new Date(now).toISOString(),update:{update_id:124,callback_query:{from:{id:42,is_bot:false},data:'mp:42:123:publish',message:{chat:{id:42,type:'private'},from:{id:99,is_bot:true}}}},targetGroupId:c.allowedGroupId,targetTopicId:10,articleTopicId:20,sourceMessageId:55,kind:'photo',mediaPart:part(),articlePart:part(),scheduleAt:0}};}
function mock(p,fail=''){
 const msgs=new Map(),calls=[],photo=new Api.Photo({id:bigInt(321),accessHash:bigInt(654),fileReference:Buffer.from('x'),date:0,sizes:[],dcId:1}),media=new Api.MessageMediaPhoto({photo});
 return {calls,msgs,getEntity:async n=>new Api.Channel({id:bigInt(String(n).slice(4)),megagroup:true,forum:true,title:'Test',photo:new Api.ChatPhotoEmpty(),date:0}),getInputEntity:async g=>new Api.InputPeerChannel({channelId:g.id,accessHash:bigInt(1)}),
 getMessages:async(peer,{ids})=>ids.map(id=>id===55?{className:'Message',id,peerId:new Api.PeerChannel({channelId:bigInt(9876500000)}),fromId:new Api.PeerUser({userId:bigInt(99)}),message:'NNA_MEDIA_STAGE:'+p.delivery.requestKey,replyTo:{replyToTopId:3},media}:msgs.get(id)),
 invoke:async x=>{
  if(x.className==='messages.GetForumTopicsByID')return {topics:x.topics.map(id=>({className:'ForumTopic',id,closed:false}))};
  calls.push(x.className);if(x.className===fail)throw Error('network');
  if(x.className==='messages.EditMessage'){Object.assign(msgs.get(x.id),{message:x.message,entities:x.entities});return {updates:[]};}
  const id=x.className==='messages.SendMessage'?70:71,m={className:'Message',id,out:true,fromId:new Api.PeerUser({userId:bigInt(42)}),peerId:new Api.PeerChannel({channelId:bigInt(1234500000)}),message:x.message,entities:x.entities,replyTo:{replyToTopId:x.replyTo.topMsgId},...(id===71?{media}:{})};msgs.set(id,m);return {updates:[{className:'UpdateMessageID',id,randomId:x.randomId},{className:'UpdateNewChannelMessage',message:m}]};
 }};
}
test('link replacement preserves emoji offsets, unrelated links and full text',()=>{const p=part(),url='https://t.me/c/123/2/45',r=fillLink(p,url);assert.equal(r.text,'Heading\n'+url+'\n🙂');assert.equal(r.entities.find(e=>e.type==='custom_emoji').offset,r.text.indexOf('🙂'));assert.equal(r.entities.find(e=>e.type==='url').offset,8);});
test('link overflow and overlapping formatting are rejected without truncation',()=>{const p=part();p.entities.push({type:'bold',offset:7,length:7});assert.throws(()=>checkPart(p),/OVERLAP/);const q=part();q.text+='x'.repeat(4050);assert.throws(()=>checkPart(q),/TOO_LONG/);});
test('approved bundle publishes two posts then links article back to media',async()=>{const p=params(),m=mock(p),r=await publishBundle(m,c,p,x=>x,now);assert.equal(r.status,'sent');assert.deepEqual(m.calls,['messages.SendMessage','messages.SendMedia','messages.EditMessage']);assert.ok(m.msgs.get(70).message.includes(r.mediaUrl));assert.ok(m.msgs.get(71).message.includes(r.articleUrl));assert.equal(m.msgs.get(70).entities.find(e=>e.className==='MessageEntityCustomEmoji').offset,m.msgs.get(70).message.indexOf('🙂'));});
test('partial media failure preserves article evidence and never retries',async()=>{const p=params(),m=mock(p,'messages.SendMedia'),r=await publishBundle(m,c,p,x=>x,now);assert.equal(r.status,'partial');assert.equal(r.articleMessageId,70);assert.equal(r.phase,'media');assert.deepEqual(m.calls,['messages.SendMessage','messages.SendMedia']);});
test('backlink failure reports both published links instead of claiming success',async()=>{const p=params(),m=mock(p,'messages.EditMessage'),r=await publishBundle(m,c,p,x=>x,now);assert.equal(r.status,'partial');assert.ok(r.articleUrl&&r.mediaUrl);assert.equal(r.phase,'backlink');});
test('tampered actors, target topics, future/expired schedule and claims reject before writes',()=>{for(const fn of [p=>p.delivery.articleTopicId=30,p=>p.delivery.claimValidated=false,p=>p.delivery.update.callback_query.from.id=43,p=>p.delivery.scheduleAt=Math.floor(now/1000)+600,p=>p.delivery.approvedAt=new Date(now-700000).toISOString()]){const p=params();fn(p);assert.throws(()=>validateBundle(c,p,now),/NNA_/);}});
test('old approval is accepted only when claimed schedule becomes due',()=>{const p=params();p.delivery.approvedAt=new Date(now-86400000).toISOString();p.delivery.scheduleAt=Math.floor(now/1000);assert.doesNotThrow(()=>validateBundle(c,p,now));assert.throws(()=>validateBundle(c,p,now+700000),/APPROVAL_OR_SCHEDULE/);});
